shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('processing/src/test/java/org/apache/druid/query/groupby/GroupByQueryQueryToolChestTest.java')
s = p.read_text()
s = s.replace('import org.apache.druid.java.util.common.granularity.Granularities;\n', 'import org.apache.druid.java.util.common.granularity.Granularities;\nimport org.apache.druid.java.util.common.granularity.Granularity;\n')
anchor = '  @Test\n  public void testMultiColumnCacheStrategy() throws Exception\n'
new = '''  @Test
  public void testResultLevelCacheWithMultiplePostAggregators() throws IOException
  {
    final ObjectMapper objectMapper = TestHelper.makeJsonMapper();
    for (Granularity granularity : ImmutableList.of(Granularities.DAY, Granularities.ALL)) {
      final GroupByQuery query = GroupByQuery.builder()
          .setDataSource(QueryRunnerTestHelper.DATA_SOURCE)
          .setInterval("2015-09-12/2015-09-13")
          .setDimensions(
              new DefaultDimensionSpec("channel", "channel"),
              new DefaultDimensionSpec("cityName", "cityName")
          )
          .setAggregatorSpecs(QueryRunnerTestHelper.ROWS_COUNT)
          .setPostAggregatorSpecs(
              ImmutableList.of(
                  new ExpressionPostAggregator("a2", "rows * 2", null, null, TestExprMacroTable.INSTANCE),
                  new ExpressionPostAggregator("a3", "rows * 3", null, null, TestExprMacroTable.INSTANCE)
              )
          )
          .setGranularity(granularity)
          .build();
      final CacheStrategy<ResultRow, Object, GroupByQuery> strategy =
          new GroupByQueryQueryToolChest(null).getCacheStrategy(query);
      final ResultRow result = query.getResultRowHasTimestamp()
                               ? ResultRow.of(
                                   DateTimes.of("2015-09-12").getMillis(), "#en.wikipedia", null, 10516, 21032, 31548
                               )
                               : ResultRow.of("#en.wikipedia", null, 10516, 21032, 31548);

      final Object cached = objectMapper.readValue(
          objectMapper.writeValueAsBytes(strategy.prepareForCache(true).apply(result)),
          strategy.getCacheObjectClazz()
      );
      Assert.assertEquals(result, strategy.pullFromCache(true).apply(cached));
    }
  }

'''
assert s.count(anchor) == 1
p.write_text(s.replace(anchor, new + anchor))
PY
mvn test -o -pl processing -Dtest=GroupByQueryQueryToolChestTest#testResultLevelCacheWithMultiplePostAggregators -Dsurefire.rerunFailingTestsCount=0 > /tmp/druid-groupby-cache-regression.log 2>&1; result=$?; tail -70 /tmp/druid-groupby-cache-regression.log; exit "$result"

cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('processing/src/main/java/org/apache/druid/query/groupby/GroupByQueryQueryToolChest.java')
s = p.read_text()
old = '''              Iterator<PostAggregator> postItr = query.getPostAggregatorSpecs().iterator();
              int postPos = 0;
              while (postItr.hasNext() && results.hasNext()) {
                resultRow.set(postAggregatorStart + postPos, results.next());
              }
'''
new = '''              for (int postPos = 0; postPos < query.getPostAggregatorSpecs().size() && results.hasNext(); postPos++) {
                resultRow.set(postAggregatorStart + postPos, results.next());
              }
'''
assert s.count(old) == 1
s = s.replace(old, new)
s = s.replace('import org.apache.druid.query.aggregation.PostAggregator;\n', '')
p.write_text(s)
PY
mvn test -o -pl processing -Dtest=GroupByQueryQueryToolChestTest -Dsurefire.rerunFailingTestsCount=0 > /tmp/druid-groupby-cache-tests.log 2>&1; result=$?; tail -55 /tmp/druid-groupby-cache-tests.log; exit "$result"

